package com.music.bitchord.acquisition.a0

import java.io.File
import java.net.InetAddress
import java.net.InetSocketAddress
import java.net.ServerSocket
import java.net.Socket

/**
 * Fully socket-backed A0 modern P(43 -> 40/41) and incoming F proof, but strictly
 * LOOPBACK ONLY. The uploader fixture must be owned/generated by the test.
 *
 * This is NOT a live Soulseek download client:
 * - No DNS, public peer IP, real credentials, scan, discovery or background task.
 * - Both TCP endpoints are pinned to 127.0.0.1.
 * - Rights/filename/size/SHA256 gate executes before ANY socket opens.
 * - No resume, no retries, no storage outside the caller's preexisting
 *   private test directory and no Catalog/Playback/MediaStore integration.
 *
 * Public peer P and F association still needs its own design and review; the
 * correlation token is not peer authentication.
 */
internal object A0ModernLoopbackSocketTransfer {
    private const val TIMEOUT_MS = 4000
    private val loopback: InetAddress
        get() = InetAddress.getByAddress(byteArrayOf(127, 0, 0, 1))

    sealed class Outcome {
        data class Completed(val receipt: A0VerifiedByteStager.Receipt) : Outcome()
        data class Blocked(val reason: A0OpenAudioCandidateGate.Rejection) : Outcome()
    }

    fun receiveOwnedFixture(
        pPort: Int,
        reference: A0OpenAudioCandidateGate.ReviewedReference,
        listing: A0OpenAudioCandidateGate.PublicPeerListing,
        privateDirectory: File,
        onFileListenerReady: (Int) -> Unit = {}
    ): Outcome {
        require(pPort in 1..65535) { "A0 requires one valid local P port" }
        // The review gate MUST precede *all* socket effects.
        val plan = A0LicensedOneFileSession.plan(reference, listing)
        if (plan is A0LicensedOneFileSession.Plan.Blocked) {
            return Outcome.Blocked(plan.reason)
        }
        val session = (plan as A0LicensedOneFileSession.Plan.Ready).session
        require(privateDirectory.isDirectory) {
            "A0 requires an existing private test directory"
        }
        ServerSocket(0, 1, loopback).use { fileListener ->
            fileListener.soTimeout = TIMEOUT_MS
            onFileListenerReady(fileListener.localPort)
            Socket().use { peerMessages ->
                peerMessages.connect(InetSocketAddress(loopback, pPort), TIMEOUT_MS)
                peerMessages.soTimeout = TIMEOUT_MS
                session.queueUpload(peerMessages.getOutputStream())
                session.acceptUpload(
                    peerMessages.getInputStream(),
                    peerMessages.getOutputStream()
                )
                fileListener.accept().use { incomingFile ->
                    incomingFile.soTimeout = TIMEOUT_MS
                    return Outcome.Completed(
                        session.receiveFile(
                            incomingF = incomingFile.getInputStream(),
                            outgoingF = incomingFile.getOutputStream(),
                            appPrivateDirectory = privateDirectory
                        )
                    )
                }
            }
        }
    }
}
